using System.Text;using System.Text.Json;namespace QuantForge.Core;public sealed class AndroidDatasetSelectionFileStore{private readonly string _path;public AndroidDatasetSelectionFileStore(string path)=>_path=Path.GetFullPath(path);public void Save(AndroidDatasetSelection value){if(string.IsNullOrWhiteSpace(value.SelectionFingerprint))throw new InvalidOperationException("Dataset selection fingerprint is required.");Directory.CreateDirectory(Path.GetDirectoryName(_path)!);File.WriteAllText(_path,JsonSerializer.Serialize(value,new JsonSerializerOptions{WriteIndented=true}),new UTF8Encoding(false));}public AndroidDatasetSelection Load()=>JsonSerializer.Deserialize<AndroidDatasetSelection>(File.ReadAllText(_path))??throw new InvalidOperationException("Dataset selection JSON is invalid.");}
